import {
    pgTable,
    serial,
    integer,
    text,
    decimal,
    timestamp,
    jsonb,
    index,
    uniqueIndex,
} from "drizzle-orm/pg-core";

import { orgs } from '../auth.js';
import { knowledgeNodes } from './graph.js';

/**
 * Predicted Links (Link Prediction Service)
 * 
 * Stores probabilistic link predictions generated by the TransE-style
 * translational embedding approach. Each record represents a candidate
 * relationship between two knowledge nodes with a confidence score.
 * Predictions can be approved (promoted to verified edges) or rejected
 * by human reviewers.
 */
export const knowledgePredictedLinks = pgTable("knowledge_predicted_links", {
    id: serial("id").primaryKey(),
    organizationId: integer("organization_id").references(() => orgs.id, { onDelete: "cascade" }).notNull(),
    sourceNodeId: integer("source_node_id").references(() => knowledgeNodes.id, { onDelete: "cascade" }).notNull(),
    targetNodeId: integer("target_node_id").references(() => knowledgeNodes.id, { onDelete: "cascade" }).notNull(),
    predictedRelation: text("predicted_relation").notNull(),
    confidenceScore: decimal("confidence_score", { precision: 4, scale: 3 }).notNull(),
    status: text("status").notNull().default("predicted"), // "predicted" | "approved" | "rejected"
    reviewedBy: text("reviewed_by"),
    reviewedAt: timestamp("reviewed_at"),
    createdAt: timestamp("created_at").defaultNow().notNull(),
}, (table) => [
    index("predicted_link_org_idx").on(table.organizationId),
    index("predicted_link_status_idx").on(table.organizationId, table.status),
    uniqueIndex("predicted_link_pair_unique").on(table.organizationId, table.sourceNodeId, table.targetNodeId),
]);

export type KnowledgePredictedLink = typeof knowledgePredictedLinks.$inferSelect;
export type InsertKnowledgePredictedLink = typeof knowledgePredictedLinks.$inferInsert;

/**
 * Node Embeddings (Link Prediction Service)
 * 
 * Caches 128-dimensional TransE-style translational embeddings for each
 * knowledge node. Used by the Link Predictor Service to compute predicted
 * relationships via the score function: ||h + r - t||.
 * Embeddings are incrementally updated when nodes/edges within 2 hops change,
 * with full re-embedding running as a scheduled background job.
 */
export const knowledgeNodeEmbeddings = pgTable("knowledge_node_embeddings", {
    id: serial("id").primaryKey(),
    nodeId: integer("node_id").references(() => knowledgeNodes.id, { onDelete: "cascade" }).notNull(),
    organizationId: integer("organization_id").references(() => orgs.id, { onDelete: "cascade" }).notNull(),
    embedding: jsonb("embedding").notNull(), // 128-dim vector
    updatedAt: timestamp("updated_at").defaultNow().notNull(),
}, (table) => [
    uniqueIndex("node_embedding_unique").on(table.nodeId),
    index("node_embedding_org_idx").on(table.organizationId),
]);

export type KnowledgeNodeEmbedding = typeof knowledgeNodeEmbeddings.$inferSelect;
export type InsertKnowledgeNodeEmbedding = typeof knowledgeNodeEmbeddings.$inferInsert;
